class MinHeap:
    def __init__(self):
        self.a = []                             # i 的孩子是 2i+1、2i+2

    def push(self, x: int) -> None:
        a = self.a
        a.append(x)                             # 先放到最后
        i = len(a) - 1
        while i > 0 and a[(i - 1) // 2] > a[i]: # 比父节点小就往上换
            p = (i - 1) // 2
            a[i], a[p] = a[p], a[i]
            i = p

    def pop(self) -> int:
        a = self.a
        top = a[0]
        a[0] = a[-1]                            # 最后一个挪到堆顶
        a.pop()
        i = 0
        while True:
            small, l, r = i, 2 * i + 1, 2 * i + 2
            if l < len(a) and a[l] < a[small]:
                small = l
            if r < len(a) and a[r] < a[small]:
                small = r
            if small == i:                      # 两个孩子都不比它小
                break
            a[i], a[small] = a[small], a[i]
            i = small
        return top

    def peek(self) -> int:
        return self.a[0]

    def size(self) -> int:
        return len(self.a)

