class MinHeap {
    private final List<Integer> a = new ArrayList<>();      // i 的孩子是 2i+1、2i+2

    public void push(int x) {
        a.add(x);                                           // 先放到最后
        int i = a.size() - 1;
        while (i > 0 && a.get((i - 1) / 2) > a.get(i)) {    // 比父节点小就往上换
            int p = (i - 1) / 2;
            swap(i, p);
            i = p;
        }
    }

    public int pop() {
        int top = a.get(0);
        int last = a.remove(a.size() - 1);
        if (a.isEmpty()) {
            return top;
        }
        a.set(0, last);                                     // 最后一个挪到堆顶
        int i = 0, n = a.size();
        while (true) {
            int small = i, l = 2 * i + 1, r = 2 * i + 2;
            if (l < n && a.get(l) < a.get(small)) {
                small = l;
            }
            if (r < n && a.get(r) < a.get(small)) {
                small = r;
            }
            if (small == i) {                               // 两个孩子都不比它小
                break;
            }
            swap(i, small);
            i = small;
        }
        return top;
    }

    public int peek() {
        return a.get(0);
    }

    public int size() {
        return a.size();
    }

    private void swap(int i, int j) {
        int t = a.get(i);
        a.set(i, a.get(j));
        a.set(j, t);
    }
}

