class Solution:
    def lastStoneWeight(self, stones: List[int]) -> int:
        heap = [-x for x in stones]             # heapq 是最小堆，存相反数当最大堆用
        heapq.heapify(heap)                     # O(n) 建堆
        while len(heap) > 1:
            y = -heapq.heappop(heap)            # 最重的
            x = -heapq.heappop(heap)            # 第二重的
            if x != y:
                heapq.heappush(heap, -(y - x))  # 碎了还剩 y - x
        return -heap[0] if heap else 0

