class Solution {
    public int lastStoneWeight(int[] stones) {
        PriorityQueue<Integer> heap = new PriorityQueue<>((a, b) -> b - a);    // 传比较器变成最大堆
        for (int x : stones) {
            heap.offer(x);
        }
        while (heap.size() > 1) {
            int y = heap.poll();                    // 最重的
            int x = heap.poll();                    // 第二重的
            if (x != y) {
                heap.offer(y - x);                  // 碎了还剩 y - x
            }
        }
        return heap.isEmpty() ? 0 : heap.peek();
    }
}

