// container/heap 要求自己的类型实现 Len、Less、Swap、Push、Pop
type maxHeap []int

func (h maxHeap) Len() int           { return len(h) }
func (h maxHeap) Less(i, j int) bool { return h[i] > h[j] } // 大的排前面：最大堆
func (h maxHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *maxHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *maxHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func lastStoneWeight(stones []int) int {
	h := maxHeap(append([]int{}, stones...))
	heap.Init(&h)                            // O(n) 建堆
	for h.Len() > 1 {
		y := heap.Pop(&h).(int) // 最重的
		x := heap.Pop(&h).(int) // 第二重的
		if x != y {
			heap.Push(&h, y-x) // 碎了还剩 y - x
		}
	}
	if h.Len() == 0 {
		return 0
	}
	return h[0]
}

